const Target = require("/work/target/confucious.js");

module.exports.fuzz = function(data) {
  const provider = new FuzzedDataProvider(data);
  const instance = new Target();

  function pollutingOrRandomString(maxLen) {
    const choice = provider.consumeIntegralInRange(0, 9);
    if (choice === 0) return "__proto__";
    if (choice === 1) return "constructor";
    if (choice === 2) return "prototype";
    if (choice === 3) return "__proto__:polluted";
    return provider.consumeString(maxLen);
  }

  const partCount = provider.consumeIntegralInRange(1, 4);
  const parts = [];
  for (let i = 0; i < partCount; i++) {
    const len = provider.consumeIntegralInRange(0, 20);
    // bias towards polluting keys
    if (provider.consumeBoolean() && provider.consumeBoolean()) {
      parts.push(pollutingOrRandomString(len));
    } else {
      parts.push(provider.consumeString(len));
    }
  }
  const key = parts.join(":");

  let value;
  const typeChoice = provider.consumeIntegralInRange(0, 3);
  if (typeChoice === 0) {
    value = provider.consumeString(50);
  } else if (typeChoice === 1) {
    value = provider.consumeIntegralInRange(-100000, 100000);
  } else if (typeChoice === 2) {
    value = provider.consumeBoolean();
  } else {
    // object branch -> triggers extend(true, {}, value)
    const k = pollutingOrRandomString(20);
    const v = provider.consumeString(20);
    value = {};
    value[k] = v;
    // nested object with polluting key
    if (provider.consumeBoolean()) {
      const k2 = pollutingOrRandomString(20);
      const inner = {};
      inner[k2] = provider.consumeString(20);
      value[k] = inner;
    }
    // also try to parse a JSON string from fuzzer data to get deep __proto__ structures
