        const jsonStr = provider.consumeRemainingAsString();
        const parsed = JSON.parse(jsonStr);
        if (parsed && typeof parsed === 'object') {
          value = parsed;
        }
      } catch (e) {}
    }
  }

  instance.set(key, value);
};

